import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./Questionnaire.css";

function Questionnaire({ onNext }) {
  const navigate = useNavigate();

  const [formData, setFormData] = useState({
    incomeRange: "",
    spendingRange: "",
    savingRange: ""
  });

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleContinue = () => {
    if (onNext) {
      onNext(formData);
    }
    navigate("/spending");
  };

  return (
    <div className="questionnaire-container">
      <div className="questionnaire-card">
        <h2 className="questionnaire-title">Financial Questionnaire</h2>

        <div className="form-group">
          <label className="form-label">Income Range</label>
          <select
            name="incomeRange"
            className="form-select"
            value={formData.incomeRange}
            onChange={handleChange}
          >
            <option value="">Select range</option>
            <option>Below 10,000</option>
            <option>10,000 - 30,000</option>
            <option>30,000 - 60,000</option>
            <option>Above 60,000</option>
          </select>
        </div>

        <div className="form-group">
          <label className="form-label">Spending Range</label>
          <select
            name="spendingRange"
            className="form-select"
            value={formData.spendingRange}
            onChange={handleChange}
          >
            <option value="">Select range</option>
            <option>Below 5,000</option>
            <option>5,000 - 15,000</option>
            <option>15,000 - 30,000</option>
            <option>Above 30,000</option>
          </select>
        </div>

        <div className="form-group">
          <label className="form-label">Saving Range</label>
          <select
            name="savingRange"
            className="form-select"
            value={formData.savingRange}
            onChange={handleChange}
          >
            <option value="">Select range</option>
            <option>Below 2,000</option>
            <option>2,000 - 10,000</option>
            <option>10,000 - 25,000</option>
            <option>Above 25,000</option>
          </select>
        </div>

        <button className="next-button" onClick={handleContinue}>
          Continue
        </button>
      </div>
    </div>
  );
}

export default Questionnaire;
